#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

static int is_tag_char(char c) {
    return (c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='/'||c=='!'||c=='-'||c==':';
}

static const char* decode_entity(const char* s, size_t n, char* out, size_t* out_len) {
    if (n >= 5 && strncmp(s, "&amp;", 5)==0) { out[0]='&'; *out_len=1; return s+5; }
    if (n >= 4 && strncmp(s, "&lt;", 4)==0) { out[0]='<'; *out_len=1; return s+4; }
    if (n >= 4 && strncmp(s, "&gt;", 4)==0) { out[0]='>'; *out_len=1; return s+4; }
    if (n >= 6 && strncmp(s, "&quot;", 6)==0) { out[0]='"'; *out_len=1; return s+6; }
    if (n >= 5 && strncmp(s, "&#39;", 5)==0) { out[0]='\''; *out_len=1; return s+5; }
    if (n >= 6 && strncmp(s, "&nbsp;", 6)==0) { out[0]=' '; *out_len=1; return s+6; }
    out[0]='&'; *out_len=1; return s+1;
}

typedef struct {
    char* text;
    char* links;
} clean_result_t;

static void append_char(char** buf, size_t* len, size_t* cap, char c) {
    if (*len + 2 >= *cap) {
        *cap = (*cap==0) ? 1024 : (*cap*2);
        *buf = (char*)realloc(*buf, *cap);
    }
    (*buf)[(*len)++] = c;
    (*buf)[*len] = 0;
}

static void append_str(char** buf, size_t* len, size_t* cap, const char* s, size_t n) {
    for (size_t i=0;i<n;i++) append_char(buf, len, cap, s[i]);
}

static void extract_href_or_src(const char* tag, size_t tag_len, char** links, size_t* llen, size_t* lcap) {
    const char* p = tag;
    const char* end = tag + tag_len;
    while (p < end) {
        if ((*p=='h'||*p=='H') && p+5<=end && strncmp(p,"href",4)==0) {
            p += 4;
            while (p<end && (*p==' '||*p=='=')) p++;
            if (p>=end) return;
            char quote = *p;
            if (quote!='"' && quote!='\'') continue;
            p++;
            const char* q = p;
            while (q<end && *q!=quote) q++;
            if (q>p) {
                append_str(links, llen, lcap, p, (size_t)(q-p));
                append_char(links, llen, lcap, '\n');
            }
            return;
        }
        if ((*p=='s'||*p=='S') && p+4<=end && strncmp(p,"src",3)==0) {
            p += 3;
            while (p<end && (*p==' '||*p=='=')) p++;
            if (p>=end) return;
            char quote = *p;
            if (quote!='"' && quote!='\'') continue;
            p++;
            const char* q = p;
            while (q<end && *q!=quote) q++;
            if (q>p) {
                append_str(links, llen, lcap, p, (size_t)(q-p));
                append_char(links, llen, lcap, '\n');
            }
            return;
        }
        p++;
    }
}

clean_result_t html_clean(const char* html) {
    clean_result_t r = {0};
    size_t tlen=0,tcap=0,llen=0,lcap=0;
    const char* p = html;
    const size_t n = strlen(html);
    enum { TEXT, TAG, SCRIPT, STYLE } state = TEXT;
    int tag_depth = 0;
    const char* tag_start = NULL;
    for (size_t i=0;i<n;i++) {
        char c = p[i];
        if (state == TEXT) {
            if (c=='<') {
                state = TAG;
                tag_depth = 1;
                tag_start = p+i;
            } else if (c=='&') {
                char buf[8];
                size_t elen = 0;
                const char* next = decode_entity(p+i, n-i, buf, &elen);
                append_str(&r.text, &tlen, &tcap, buf, elen);
                i = (size_t)(next - p - 1);
            } else {
                append_char(&r.text, &tlen, &tcap, c);
            }
        } else if (state == TAG) {
            if (c=='<') {
                tag_depth++;
            } else if (c=='>') {
                tag_depth--;
                if (tag_depth <= 0) {
                    size_t tag_len = (size_t)((p+i) - tag_start);
                    extract_href_or_src(tag_start, tag_len, &r.links, &llen, &lcap);
                    state = TEXT;
                }
                continue;
            }
            if ((c=='s' || c=='S') && i+6<n && (strncasecmp(p+i,"script",6)==0)) {
                state = SCRIPT;
            } else if ((c=='s' || c=='S') && i+5<n && (strncasecmp(p+i,"style",5)==0)) {
                state = STYLE;
            }
        } else if (state == SCRIPT) {
            if (c=='<' && i+8<n && strncasecmp(p+i,"</script>",9)==0) {
                state = TAG;
                tag_depth=1;
            }
        } else if (state == STYLE) {
            if (c=='<' && i+7<n && strncasecmp(p+i,"</style>",8)==0) {
                state = TAG;
                tag_depth=1;
            }
        }
    }
    if (!r.text) r.text = strdup("");
    if (!r.links) r.links = strdup("");
    return r;
}

void html_clean_free(clean_result_t r) {
    free(r.text);
    free(r.links);
}
