#include <string.h>
#include <unicode/unorm2.h>
#include <unicode/ustring.h>
#include <unicode/ucasemap.h>

char* normalize_nfkc_lower(const char* utf8) {
    if (!utf8) return NULL;
    UErrorCode status = U_ZERO_ERROR;
    const UNormalizer2* norm = unorm2_getNFKCInstance(&status);
    if (U_FAILURE(status)) return NULL;
    int32_t src_len = (int32_t)strlen(utf8);
    int32_t u16_cap = src_len * 2 + 16;
    UChar* u16 = (UChar*)malloc((size_t)u16_cap * sizeof(UChar));
    int32_t u16_len = 0;
    u_strFromUTF8(u16, u16_cap, &u16_len, utf8, src_len, &status);
    if (U_FAILURE(status)) { free(u16); return NULL; }
    int32_t norm_cap = u16_len * 2 + 16;
    UChar* norm_buf = (UChar*)malloc((size_t)norm_cap * sizeof(UChar));
    int32_t norm_len = unorm2_normalize(norm, u16, u16_len, norm_buf, norm_cap, &status);
    free(u16);
    if (U_FAILURE(status)) { free(norm_buf); return NULL; }
    UCaseMap* csm = ucasemap_open("", 0, &status);
    if (U_FAILURE(status)) { free(norm_buf); return NULL; }
    int32_t lower_cap = norm_len * 2 + 16;
    UChar* lower_buf = (UChar*)malloc((size_t)lower_cap * sizeof(UChar));
    int32_t lower_len = ucasemap_utf16ToLower(csm, lower_buf, lower_cap, norm_buf, norm_len, &status);
    ucasemap_close(csm);
    free(norm_buf);
    if (U_FAILURE(status)) { free(lower_buf); return NULL; }
    int32_t out_cap = lower_len * 4 + 16;
    char* out = (char*)malloc((size_t)out_cap);
    int32_t out_len = 0;
    u_strToUTF8(out, out_cap, &out_len, lower_buf, lower_len, &status);
    free(lower_buf);
    if (U_FAILURE(status)) { free(out); return NULL; }
    out[out_len] = 0;
    return out;
}
